/* The airport pages now carry their empty legs as real HTML, written by
   update-airport-legs.py. All this does is hide a card once its flight
   has gone, so the page stops showing it on the day it leaves without
   being rebuilt. Same rule as /empty-legs: strictly after today. */
(function () {
  function todayKey() {
    var n = new Date();
    return n.getFullYear() * 10000 + (n.getMonth() + 1) * 100 + n.getDate();
  }
  function prune() {
    var sec = document.getElementById('empty-legs-sec');
    if (!sec) return;
    var t = todayKey();
    var cards = sec.querySelectorAll('.el-card[data-sk]');
    if (!cards.length) return;
    var left = 0;
    for (var i = 0; i < cards.length; i++) {
      var sk = parseInt(cards[i].getAttribute('data-sk'), 10) || 0;
      if (sk > t) { left++; } else { cards[i].style.display = 'none'; }
    }
    var row = sec.querySelector('.el-row');
    var empty = sec.querySelector('.el-empty');
    if (!left) {
      if (row) row.style.display = 'none';
      if (empty) empty.style.display = 'block';
    }
  }
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', prune);
  } else {
    prune();
  }
})();
